tool_input.command:
awk -F'|' '
BEGIN { print "{\"vectors\": {" > "submission/answers.json" }
{
  key=$1
  line=$2
  # extract content between the vector [ and ]
  sub(/.*"vector":\[/, "", line)
  sub(/\].*/, "", line)
  # line now: "A0002",-0.9637,3.0881,-2.3541,3.0469
  # drop the leading quoted account_id element
  sub(/^"[^"]*",/, "", line)
  entries[NR] = "  \"" key "\": [" line "]"
  count=NR
}
END {
  for (i=1; i<=count; i++) {
    sep = (i<count) ? "," : ""
    print entries[i] sep >> "submission/answers.json"
  }
  print "}}" >> "submission/answers.json"
}
' .tmp/vectors.txt
cat submission/answers.json
